using System;
using System.Drawing;
using System.Drawing.Drawing2D;
using System.Globalization;
using System.Linq;
using System.Windows.Forms;
namespace AshkanFitPro {
public partial class ExecutiveDashboardForm : Form {
 readonly Store store; readonly bool fa;
 readonly Color teal=Color.FromArgb(42,220,186),pink=Color.FromArgb(255,126,153);
 public ExecutiveDashboardForm(Store data,bool persian){store=data??new Store();fa=persian;InitializeComponent();Text=Tr("داشبورد مدیریتی اشکان فیت","AshkanFit Pro | Executive Dashboard");titleLabel.Text=Tr("نمای مدیریتی باشگاه","EXECUTIVE OVERVIEW");closeButton.Text=Tr("بستن","Close");closeButton.Click+=(s,e)=>Close();RefreshSummary();chartPanel.Paint+=PaintChart;}
 string Tr(string a,string b){return fa?a:b;}
 void RefreshSummary(){var now=DateTime.Today;int active=store.Members.Count(m=>m.Expiry.Date>=now);int expired=store.Members.Count(m=>m.Expiry.Date<now);int soon=store.Members.Count(m=>m.Expiry.Date>=now&&m.Expiry.Date<=now.AddDays(30));int visits=store.AttendanceRecords.Count(a=>a.CheckedInAt.Date==now);var first=new DateTime(now.Year,now.Month,1);decimal income=store.Payments.Where(x=>x.Date>=first&&x.Date<first.AddMonths(1)).Sum(x=>x.Amount);decimal expenses=store.Expenses.Where(x=>x.Date>=first&&x.Date<first.AddMonths(1)).Sum(x=>x.Amount);
 cards.Controls.Clear();AddCard(Tr("اعضای فعال","ACTIVE MEMBERS"),active.ToString("N0"),teal);AddCard(Tr("اشتراک منقضی","EXPIRED"),expired.ToString("N0"),pink);AddCard(Tr("تمدید تا ۳۰ روز","RENEWAL IN 30 DAYS"),soon.ToString("N0"),Color.FromArgb(250,190,90));AddCard(Tr("حضور امروز","TODAY'S VISITS"),visits.ToString("N0"),Color.FromArgb(130,170,255));AddCard(Tr("دریافتی ماه","MONTHLY RECEIPTS"),income.ToString("N0"),teal);AddCard(Tr("مانده خالص ماه","MONTHLY NET"),(income-expenses).ToString("N0"),income>=expenses?teal:pink);chartTitle.Text=Tr("مقایسه دریافت‌ها و هزینه‌ها در شش ماه اخیر","RECEIPTS VS EXPENSES · LAST 6 MONTHS");noteLabel.Text=Tr("شاخص‌ها بر اساس اطلاعات فعلی برنامه محاسبه می‌شوند؛ مانده خالص، سود حسابداری نیست.","Figures use current application records; net receipts are not accounting profit.");chartPanel.Invalidate();}
 void AddCard(string caption,string value,Color highlight){var panel=new Panel{Width=235,Height=105,Margin=new Padding(8),BackColor=Color.FromArgb(24,43,63)};var name=new Label{Text=caption,ForeColor=Color.FromArgb(184,205,221),Font=new Font("Segoe UI",9,FontStyle.Bold),Location=new Point(15,13),AutoSize=true};var number=new Label{Text=value,ForeColor=highlight,Font=new Font("Segoe UI",20,FontStyle.Bold),Location=new Point(15,40),AutoSize=true};panel.Controls.Add(name);panel.Controls.Add(number);cards.Controls.Add(panel);}
 void PaintChart(object sender,PaintEventArgs e){var g=e.Graphics;g.SmoothingMode=SmoothingMode.AntiAlias;g.Clear(Color.FromArgb(19,32,51));var rect=chartPanel.ClientRectangle;if(rect.Width<330||rect.Height<190)return;int left=65,top=35,right=22,bottom=45;float width=rect.Width-left-right,height=rect.Height-top-bottom;var now=DateTime.Today;var months=Enumerable.Range(-5,6).Select(offset=>new DateTime(now.Year,now.Month,1).AddMonths(offset)).ToArray();var income=months.Select(m=>store.Payments.Where(x=>x.Date>=m&&x.Date<m.AddMonths(1)).Sum(x=>x.Amount)).ToArray();var costs=months.Select(m=>store.Expenses.Where(x=>x.Date>=m&&x.Date<m.AddMonths(1)).Sum(x=>x.Amount)).ToArray();decimal max=Math.Max(1m,income.Concat(costs).Max());using(var line=new Pen(Color.FromArgb(50,85,106)))using(var font=new Font("Segoe UI",9))using(var muted=new SolidBrush(Color.FromArgb(180,204,220)))using(var incomeBrush=new SolidBrush(teal))using(var costBrush=new SolidBrush(pink)){for(int j=0;j<=4;j++){float y=top+j*height/4;g.DrawLine(line,left,y,left+width,y);g.DrawString((max*(4-j)/4).ToString("N0"),font,muted,3,y-8);}float slot=width/6;float bw=Math.Min(25,slot*.23f);for(int i=0;i<6;i++){float center=left+slot*(i+.5f);float a=(float)(income[i]/max)*height,b=(float)(costs[i]/max)*height;g.FillRectangle(incomeBrush,center-bw-3,top+height-a,bw,a);g.FillRectangle(costBrush,center+3,top+height-b,bw,b);g.DrawString(months[i].ToString("MM/yy",CultureInfo.InvariantCulture),font,muted,center-19,top+height+12);}g.FillRectangle(incomeBrush,left,8,12,12);g.DrawString(Tr("دریافتی","Receipts"),font,muted,left+18,5);g.FillRectangle(costBrush,left+145,8,12,12);g.DrawString(Tr("هزینه","Expenses"),font,muted,left+163,5);}}
 }
}
}
